import software.amazon.awssdk.services.sqs.SqsClient;
import software.amazon.awssdk.services.sqs.model.*;
import org.thymeleaf.TemplateEngine;
import org.thymeleaf.context.Context;
import org.thymeleaf.templateresolver.StringTemplateResolver;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.JsonNode;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class NotificationConsumer {
    private static final Logger log = LoggerFactory.getLogger(NotificationConsumer.class);
    private final SqsClient sqsClient;
    private final String queueUrl;
    private final TemplateEngine templateEngine;
    private final ObjectMapper mapper = new ObjectMapper();
    private final ExecutorService executor = Executors.newFixedThreadPool(4);

    public NotificationConsumer(SqsClient sqsClient, String queueUrl) {
        this.sqsClient = sqsClient;
        this.queueUrl = queueUrl;
        this.templateEngine = new TemplateEngine();
        StringTemplateResolver resolver = new StringTemplateResolver();
        resolver.setTemplateMode("HTML");
        this.templateEngine.setTemplateResolver(resolver);
    }

    public void pollAndProcess() {
        while (true) {
            try {
                ReceiveMessageRequest req = ReceiveMessageRequest.builder()
                        .queueUrl(queueUrl)
                        .maxNumberOfMessages(10)
                        .waitTimeSeconds(20)
                        .build();

                List<Message> messages = sqsClient.receiveMessage(req).messages();
                for (Message msg : messages) {
                    executor.submit(() -> processMessage(msg));
                }
            } catch (Exception e) {
                log.error("Polling error", e);
                sleep(5000);
            }
        }
    }

    private void processMessage(Message message) {
        try {
            JsonNode payload = mapper.readTree(message.body());
            String eventType = payload.get("eventType").asText();
            String recipientEmail = payload.get("recipient").asText();

            // Template is constructed from message attributes for customization
            String templateBody = payload.has("customTemplate") 
                ? payload.get("customTemplate").asText()
                : getDefaultTemplate(eventType);

            // Build context from message data
            Context ctx = new Context();
            ctx.setVariable("recipient", recipientEmail);
            ctx.setVariable("eventType", eventType);

            if (payload.has("data")) {
                JsonNode data = payload.get("data");
                data.fields().forEachRemaining(field -> 
                    ctx.setVariable(field.getKey(), field.getValue().asText()));
            }

            // SSTI vulnerability: user-controlled template processed by Thymeleaf
            String rendered = templateEngine.process(templateBody, ctx);

            sendNotification(recipientEmail, rendered);
            deleteMessage(message);

            log.info("Processed notification for {} type={}", recipientEmail, eventType);
        } catch (Exception e) {
            log.error("Failed to process message: {}", message.messageId(), e);
        }
    }

    private String getDefaultTemplate(String eventType) {
        switch (eventType) {
            case "welcome":
                return "<html><body><h1>Welcome, <span th:text=\"${recipient}\"></span>!</h1></body></html>";
            case "alert":
                return "<html><body><h1>Alert</h1><p th:text=\"${message}\"></p></body></html>";
            default:
                return "<html><body><p th:text=\"${recipient}\">Notification</p></body></html>";
        }
    }

    private void sendNotification(String recipient, String body) {
        // Sends via SES or internal SMTP relay
        log.debug("Sending to {}: {}", recipient, body.substring(0, Math.min(100, body.length())));
    }

    private void deleteMessage(Message message) {
        sqsClient.deleteMessage(DeleteMessageRequest.builder()
                .queueUrl(queueUrl)
                .receiptHandle(message.receiptHandle())
                .build());
    }

    private void sleep(long ms) {
        try { Thread.sleep(ms); } catch (InterruptedException ignored) {}
    }

    public static void main(String[] args) {
        SqsClient client = SqsClient.builder().build();
        String queue = System.getenv("NOTIFICATION_QUEUE_URL");
        new NotificationConsumer(client, queue).pollAndProcess();
    }
}
